152	        for (int i = 0; i < buyers; i++) {
153	            orders.add(placeOrder(checkout().cpf("1000000000" + i).item("MOC-001", 1).json()));
154	        }
155	        CountDownLatch start = new CountDownLatch(1);
156	        ExecutorService pool = Executors.newFixedThreadPool(buyers);
157	        List<Future<Integer>> results = new ArrayList<>();
158	        for (int i = 0; i < buyers; i++) {
159	            String id = orders.get(i);
