161	            Callable<Integer> payment = () -> {
162	                start.await();
163	                return pay(id, tx, now()).andReturn().getResponse().getStatus();
164	            };
165	            results.add(pool.submit(payment));
166	        }
167	        start.countDown();
168	        List<Integer> statuses = new ArrayList<>();
169	        for (Future<Integer> result : results) {
